124	        HttpHeaders headers = new HttpHeaders();
125	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
126	        String address = addressNormalizer.normalize(owner.getAddress());
127	        if (addressNormalizer.isBlank(address)) {
128	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
129	        }
130	        owner.setAddress(address);
131	        Optional<String> e164Telephone = telephoneNormalizer.toE164(owner.getTelephone());
132	        if (e164Telephone.isEmpty()) {
133	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
