135	        String telephone = e164Telephone.get();
136	        String email = emailNormalizer.normalize(owner.getEmail());
137	        if (email != null && !emailNormalizer.isValid(email)) {
138	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
139	        }
140	        if (clinicService.existsOwnerByTelephone(telephone)) {
141	            return new ResponseEntity<>(HttpStatus.CONFLICT);
142	        }
143	        if (clinicService.countOwnersByCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
144	            return new ResponseEntity<>(HttpStatus.CONFLICT);
145	        }
146	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
147	        if (!sharesHousehold
148	            && clinicService.existsOwnerByLastNameAndAddress(owner.getLastName(), owner.getAddress())) {
149	            return new ResponseEntity<>(HttpStatus.CONFLICT);
